(()=>{'use strict';
const screen=document.querySelector('#screen'),content=document.querySelector('#content'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const paths={mute:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>',speaker:'<path d="M4 9h4l5-4v14l-5-4H4zM17 8a6 6 0 0 1 0 8M20 5a10 10 0 0 1 0 14"/>',endVoice:'<path d="M5 5l14 14M19 5L5 19"/>'};
function icons(){for(const [action,path]of Object.entries(paths)){const button=content.querySelector(`[data-action="${action}"]`);if(button)button.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true">${path}</svg>`;}}
let lastPage='';function enhance(){const page=location.hash;if(page!==lastPage){lastPage=page;const root=content.firstElementChild;if(root&&!reduced){root.animate([{opacity:0,transform:'translateY(18px) scale(.97)',filter:'blur(3px)'},{opacity:1,transform:'translateY(0) scale(1)',filter:'blur(0)'}],{duration:420,easing:'cubic-bezier(.16,1,.3,1)'});content.querySelectorAll('.card').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(15px)'},{opacity:1,transform:'translateY(0)'}],{duration:380,delay:i*65,fill:'backwards',easing:'ease-out'}));}}icons();}
new MutationObserver(records=>{if(records.some(r=>r.target===content))enhance();}).observe(content,{childList:true});enhance();
screen.addEventListener('pointerdown',e=>{const b=e.target.closest('button');if(!b||reduced||b.classList.contains('orb-button'))return;const rect=b.getBoundingClientRect(),r=document.createElement('span');r.className='ripple';r.style.left=`${(e.clientX-rect.left)*b.offsetWidth/rect.width-9}px`;r.style.top=`${(e.clientY-rect.top)*b.offsetHeight/rect.height-9}px`;b.append(r);setTimeout(()=>r.remove(),600);});
new MutationObserver(()=>{if(reduced)return;for(const id of ['voiceTitle','voiceCaption']){const el=document.getElementById(id);el?.animate([{opacity:0,transform:'translateY(7px)'},{opacity:1,transform:'translateY(0)'}],{duration:350,easing:'ease-out'});}}).observe(content,{characterData:true,childList:true,subtree:true});
})();
const wristObserver=new MutationObserver(()=>{const list=document.querySelector('.wrist-list');if(!list||list.dataset.wristReady)return;list.dataset.wristReady='true';function scaleRows(){const box=list.getBoundingClientRect(),mid=box.top+box.height/2;for(const row of list.querySelectorAll('.wrist-row')){const r=row.getBoundingClientRect(),distance=Math.min(1,Math.abs((r.top+r.height/2)-mid)/(box.height/2));row.style.transform=`scale(${1-distance*.13})`;row.style.opacity=String(1-distance*.25);}}list.addEventListener('scroll',scaleRows,{passive:true});requestAnimationFrame(scaleRows);});wristObserver.observe(document.querySelector('#content'),{childList:true});
